import{_ as t,o as s,c as a,a2 as n}from"./chunks/framework.Ddyno5UB.js";const m=JSON.parse('{"title":"Container Fundamentals","description":"","frontmatter":{},"headers":[],"relativePath":"containers/1-fundamentals.md","filePath":"containers/1-fundamentals.md"}'),o={name:"containers/1-fundamentals.md"};function i(r,e,l,c,d,u){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="container-fundamentals" tabindex="-1">Container Fundamentals <a class="header-anchor" href="#container-fundamentals" aria-label="Permalink to &quot;Container Fundamentals&quot;">​</a></h1><p>Before running a single Docker or Podman command, it is crucial to understand that <strong>&quot;containers&quot; do not actually exist as a distinct object in the Linux kernel.</strong></p><p>Unlike Virtual Machines (VMs), which use a hypervisor to virtualize entire chunks of physical hardware (CPU, RAM, Disks), a container is simply a normal Linux process that has been heavily restricted using three native Linux kernel features: <strong>Namespaces</strong>, <strong>cgroups</strong>, and <strong>UnionFS</strong>.</p><h2 id="_1-namespaces-isolation" tabindex="-1">1. Namespaces (Isolation) <a class="header-anchor" href="#_1-namespaces-isolation" aria-label="Permalink to &quot;1. Namespaces (Isolation)&quot;">​</a></h2><p>Namespaces provide <em>isolation</em>. They trick a process into thinking it has its own dedicated operating system, when in reality, it is sharing the kernel with thousands of other processes.</p><p>When you start a container, Linux creates dedicated namespaces for it:</p><ul><li><strong>PID Namespace:</strong> The container thinks its main application is Process ID <code>1</code>. (On the host machine, it might be PID <code>34502</code>).</li><li><strong>NET Namespace:</strong> The container gets its own isolated network stack, virtual ethernet interface (veth), and IP address.</li><li><strong>MNT Namespace:</strong> The container cannot see the host&#39;s <code>/var</code> or <code>/etc</code>. It only sees its own isolated filesystem (like a modern <code>chroot</code>).</li><li><strong>USER Namespace:</strong> A process running as <code>root</code> inside the container can be mapped to a completely unprivileged user on the host machine.</li></ul><h2 id="_2-cgroups-resource-limits" tabindex="-1">2. cgroups (Resource Limits) <a class="header-anchor" href="#_2-cgroups-resource-limits" aria-label="Permalink to &quot;2. cgroups (Resource Limits)&quot;">​</a></h2><p>While namespaces isolate <em>visibility</em>, Control Groups (<code>cgroups</code>) isolate <em>resources</em>.</p><p>If a bug causes a Node.js app inside a container to enter an infinite loop and consume 100% of the CPU, it would normally crash the entire host server. <code>cgroups</code> prevent this by enforcing hard limits:</p><ul><li><strong>CPU:</strong> &quot;This container can only use a maximum of 0.5 CPU cores.&quot;</li><li><strong>Memory:</strong> &quot;This container is strictly limited to 512MB of RAM. If it exceeds this, the kernel will OOM-kill it.&quot;</li></ul><h2 id="_3-unionfs-layered-filesystems" tabindex="-1">3. UnionFS (Layered Filesystems) <a class="header-anchor" href="#_3-unionfs-layered-filesystems" aria-label="Permalink to &quot;3. UnionFS (Layered Filesystems)&quot;">​</a></h2><p>Containers boot instantly (in milliseconds) because they don&#39;t actually boot an OS. They just unpack an image.</p><p>Container images are built using <strong>Union Filesystems (UnionFS)</strong> (like <code>overlay2</code>). Instead of a single massive 1GB file, an image is a stack of read-only layers.</p><ol><li><strong>Layer 1:</strong> The Base OS (e.g., Ubuntu).</li><li><strong>Layer 2:</strong> Security updates applied.</li><li><strong>Layer 3:</strong> Nginx installed.</li><li><strong>Layer 4:</strong> Your specific HTML code added.</li></ol><p>When a container runs, Docker places a thin <strong>Read/Write (R/W) layer</strong> on the very top of this stack. If the container deletes a file from Layer 1, it doesn&#39;t actually delete it; it just marks it as deleted in the top R/W layer.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Because the underlying image layers are strictly Read-Only, <strong>hundreds of containers can share the exact same underlying base image simultaneously</strong>, saving massive amounts of disk space and RAM.</p></div><h2 id="vms-vs-containers" tabindex="-1">VMs vs Containers <a class="header-anchor" href="#vms-vs-containers" aria-label="Permalink to &quot;VMs vs Containers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Virtual Machine (VM)</th><th>Container</th></tr></thead><tbody><tr><td><strong>Architecture</strong></td><td>Virtualizes the Hardware</td><td>Virtualizes the OS (shares the Host Kernel)</td></tr><tr><td><strong>Boot Time</strong></td><td>Minutes</td><td>Milliseconds</td></tr><tr><td><strong>Size</strong></td><td>Gigabytes</td><td>Megabytes</td></tr><tr><td><strong>Overhead</strong></td><td>High (runs a full Guest OS)</td><td>Near Zero (just normal Linux processes)</td></tr><tr><td><strong>Isolation</strong></td><td>Absolute (Hypervisor enforced)</td><td>Strong (Namespace/cgroup enforced)</td></tr></tbody></table>',19)])])}const p=t(o,[["render",i]]);export{m as __pageData,p as default};
